    /**
     * @ignore
     * @method
     * @name massive#parseRfc3339
     * @description parses an rfc3339 datetime carrying an explicit utc offset, which the base parse8601 does not accept
     * @param {string} datetime an rfc3339 datetime, e.g. 2020-11-10T17:37:37-05:00
     * @returns {int} the unix timestamp in milliseconds
     */
    public Object parseRfc3339(Object datetime)
    {
        if (Helpers.isTrue(Helpers.isEqual(datetime, null)))
        {
            return null;
        }
        // the trailing 6 characters are the utc offset, e.g. -05:00, on anything
        // shorter or on a 'Z' suffixed datetime the sign check below falls through
        Object offsetPart = Helpers.slice(datetime, Helpers.opNeg(6), null);
        Object sign = Helpers.slice(offsetPart, 0, 1);
        if (Helpers.isTrue(Helpers.isTrue((!Helpers.isEqual(sign, "+"))) && Helpers.isTrue((!Helpers.isEqual(sign, "-")))))
        {
            return this.parse8601(datetime);
        }
        Object timestamp = this.parse8601(Helpers.add(Helpers.slice(datetime, 0, Helpers.opNeg(6)), "Z"));
        if (Helpers.isTrue(Helpers.isEqual(timestamp, null)))
        {
            return null;
        }
        Object hours = this.parseToInt(Helpers.slice(offsetPart, 1, 3));
        Object minutes = this.parseToInt(Helpers.slice(offsetPart, 4, 6));
        Object offset = Helpers.multiply(Helpers.multiply(this.sum(Helpers.multiply(hours, 60), minutes), 60), 1000);
        if (Helpers.isTrue(Helpers.isEqual(sign, "-")))
        {
            return this.sum(timestamp, offset);
        }
        return Helpers.subtract(timestamp, offset);
    }

