    public Object parseMarket(Object market)
    {
        Object id = this.safeString(market, "ticker");
        // a stock ticker is not a currency code, it must not go through
        // safeCurrencyCode - tickers such as LINK, COMP or UNI would be rewritten
        Object base = id;
        Object quoteId = this.safeString(market, "currency_name", "usd");
        Object quote = ((String)quoteId).toUpperCase();
        Object symbol = Helpers.add(Helpers.add(base, "/"), quote);
        final Object finalBase = base;
        return this.safeMarketStructure(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "symbol", symbol );
            put( "base", finalBase );
            put( "quote", quote );
            put( "baseId", id );
            put( "quoteId", quoteId );
            put( "settle", null );
            put( "settleId", null );
            put( "type", "spot" );
            put( "spot", true );
            put( "stock", true );
            put( "margin", false );
            put( "swap", false );
            put( "future", false );
            put( "option", false );
            put( "active", MassiveCore.this.safeBool(market, "active") );
            put( "contract", false );
            put( "linear", null );
            put( "inverse", null );
            put( "taker", 0 );
            put( "maker", 0 );
            put( "contractSize", null );
            put( "expiry", null );
            put( "expiryDatetime", null );
            put( "strike", null );
            put( "optionType", null );
            put( "precision", new java.util.HashMap<String, Object>() {{
                put( "amount", MassiveCore.this.parseNumber("1") );
                put( "price", MassiveCore.this.parseNumber("0.0001") );
            }} );
            put( "limits", new java.util.HashMap<String, Object>() {{
                put( "leverage", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "amount", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "price", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
                put( "cost", new java.util.HashMap<String, Object>() {{
                    put( "min", null );
                    put( "max", null );
                }} );
            }} );
            put( "created", MassiveCore.this.parse8601(MassiveCore.this.safeString(market, "list_date")) );
            put( "info", market );
        }});
    }

